import type {
  ComprehensionQuestion,
  DifficultyBand,
  ParagraphTask,
  SourceReference,
  StoryLesson,
  TextFeature,
  VocabularyWord,
} from "../types";

type LessonDraft = {
  sequence: number;
  title: string;
  genre: string;
  informational?: boolean;
  band: DifficultyBand;
  objective: string;
  skillTags: string[];
  pageOneSubheading: string;
  pageOne: string[];
  pageOneCallout: { label: string; text: string };
  pageTwoSubheading: string;
  pageTwo: string[];
  pageTwoCallout: { label: string; text: string };
  illustration: Omit<StoryLesson["illustration"], "src">;
  vocabulary: [VocabularyWord, VocabularyWord, VocabularyWord];
  comprehension: StoryLesson["comprehension"];
  paragraphTask: ParagraphTask;
  sourceReferences?: SourceReference[];
};

const makeQuestions = (
  lesson: number,
  questions: [
    Omit<ComprehensionQuestion, "id">,
    Omit<ComprehensionQuestion, "id">,
    Omit<ComprehensionQuestion, "id">,
    Omit<ComprehensionQuestion, "id">,
    Omit<ComprehensionQuestion, "id">,
  ],
): StoryLesson["comprehension"] =>
  questions.map((question, index) => ({
    id: `lesson-${lesson}-question-${index + 1}`,
    ...question,
  })) as StoryLesson["comprehension"];

const makeParagraphTask = (
  lesson: number,
  task: Omit<ParagraphTask, "sentenceOptions"> & {
    sentenceOptions: Array<Omit<ParagraphTask["sentenceOptions"][number], "id">>;
  },
): ParagraphTask => ({
  ...task,
  sentenceOptions: task.sentenceOptions.map((option, index) => ({
    id: `lesson-${lesson}-sentence-${index + 1}`,
    ...option,
  })),
});

const makeTextFeatures = (
  lesson: number,
  title: string,
  subheading: string,
  calloutLabel: string,
  illustrationCaption: string,
): [TextFeature, TextFeature, TextFeature, TextFeature] => [
  {
    id: `lesson-${lesson}-feature-title`,
    feature: "Title",
    location: "Above page 1",
    purpose: `Introduces the lesson as “${title}.”`,
    helpsBecause: "It prepares the reader for the central topic or mystery.",
  },
  {
    id: `lesson-${lesson}-feature-subheading`,
    feature: "Subheading",
    location: `At the start of page 2: “${subheading}”`,
    purpose: "Signals a new stage in the events or explanation.",
    helpsBecause: "It helps the reader organize ideas across the two pages.",
  },
  {
    id: `lesson-${lesson}-feature-callout`,
    feature: "Information box",
    location: `Page 1 callout labelled “${calloutLabel}”`,
    purpose: "Highlights a useful clue or fact without interrupting the passage.",
    helpsBecause: "It draws attention to information worth remembering.",
  },
  {
    id: `lesson-${lesson}-feature-caption`,
    feature: "Illustration with caption",
    location: "Beside the reading spread",
    purpose: `Shows the scene described by “${illustrationCaption}”`,
    helpsBecause: "The picture and caption help the reader visualize an important moment.",
  },
];

const makeLesson = (draft: LessonDraft): StoryLesson => ({
  id: `story-lesson-${String(draft.sequence).padStart(3, "0")}`,
  sequence: draft.sequence,
  title: draft.title,
  genre: draft.genre,
  informational: draft.informational ?? false,
  grade: 5,
  band: draft.band,
  objective: draft.objective,
  skillTags: draft.skillTags,
  pages: [
    {
      pageNumber: 1,
      subheading: draft.pageOneSubheading,
      paragraphs: draft.pageOne,
      callout: draft.pageOneCallout,
    },
    {
      pageNumber: 2,
      subheading: draft.pageTwoSubheading,
      paragraphs: draft.pageTwo,
      callout: draft.pageTwoCallout,
    },
  ],
  illustration: {
    src: `/story-adventures/illustrations/lesson-${String(draft.sequence).padStart(3, "0")}.svg`,
    ...draft.illustration,
  },
  vocabulary: draft.vocabulary,
  comprehension: draft.comprehension,
  paragraphTask: draft.paragraphTask,
  textFeatures: makeTextFeatures(
    draft.sequence,
    draft.title,
    draft.pageTwoSubheading,
    draft.pageOneCallout.label,
    draft.illustration.caption,
  ),
  sourceReferences: draft.sourceReferences ?? [],
  contentVersion: "1.0.0",
});

const vocab = (
  word: string,
  definition: string,
  synonymOne: string,
  synonymTwo: string,
  contextSentence: string,
  hint: string,
): VocabularyWord => ({
  word,
  definition,
  synonyms: [synonymOne, synonymTwo],
  contextSentence,
  hint,
});

const question = (
  classification: ComprehensionQuestion["classification"],
  prompt: string,
  modelAnswer: string,
  evidence: string,
  isOpinion = false,
): Omit<ComprehensionQuestion, "id"> => ({
  classification,
  prompt,
  modelAnswer,
  evidence,
  ...(isOpinion ? { isOpinion: true } : {}),
});

const option = (
  text: string,
  relevant: boolean,
  reason: string,
): Omit<ParagraphTask["sentenceOptions"][number], "id"> => ({
  text,
  relevant,
  reason,
});

